from numpy import *

t = array([int] * 20)


def Saisie():
    b = False
    while not (b):
        n = int(input("Donner le nombre des cases: "))
        b = 5 <= n <= 20
    return n


def Remplir(n):
    for i in range(n):
        t[i] = int(input("t[" + str(i) + "] = "))


def suppression(t, n):  #Recherche avec la boucle pour n'est pas preférée
    i = 0
    while i < n:
        for j in range(n):
            for k in range(j + 1, n):
                if t[k] == t[j]:
                    for l in range(k, n - 1):
                        t[l] = t[l + 1]
                    n -= 1
        i += 1
    return n


